window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['adsp-36']={"round":36,"cert":"adsp","questions":[{"id":"62186","number":1,"category":"데이터 이해","type":"choice","subject":"다음 데이터에 대한 설명으로 가장 적절하지 않은 것은?","choices":[{"n":1,"html":"추론, 예측, 전망, 추정을 위한 근거(basis)로 기능하는 특성을 갖는다."},{"n":2,"html":"데이터는 축적된 지식과 아이디어가 결합된 창의적인 산물이다."},{"n":3,"html":"데이터는 개별 데이터 자체로는 의미가 중요하지 않은 객관적인 사실이다."},{"n":4,"html":"다른 객체와의 상호 관계 속에서 가치를 갖는다."}],"answer":[2],"explain":{"ai":["<p>데이터는 객관적인 사실을 나타내는 정보로, 개별 데이터 자체로는 의미가 중요하지 않을 수 있지만 다른 데이터와의 관계 속에서 가치를 갖는다. 또한 추론, 예측, 전망, 추정을 위한 근거로 기능하는 특성을 갖는다. 하지만 데이터는 축적된 지식과 아이디어가 결합된 창의적인 산물은 아니다. 데이터는 사실을 기반으로 하기 때문에 창의적인 산물이 아님을 의미한다. 따라서 2번은 데이터에 대한 설명으로는 가장 적절하지 않다. 데이터는 객관적인的事實을 나타내는 정보로, 다른 객체와의 상호関係 속에서 가치를 갖는 것이 특징이다.</p>"]},"rate":67,"rateN":4757},{"id":"62187","number":2,"category":"데이터 이해","type":"choice","subject":"빅데이터가 가치 창출 측면에서 기업, 정부, 개인에게 미친 영향으로 옳지 않은 것은?","choices":[{"n":1,"html":"산업 전체의 생산성이 향상되었다."},{"n":2,"html":"개인은 맞춤형 서비스를 받거나 적시에 필요한 정보를 얻음으로써 기회비용을 절약하게 되었다."},{"n":3,"html":"기업활동의 투명성은 없어지지만 경쟁사보다 강한 경쟁력을 확보하는데 도움이 되었다."},{"n":4,"html":"비즈니스 모델을 혁신하거나 신사업 발굴에 활용할 수 있게 되었다."}],"answer":[3],"explain":{"ai":["<p>빅데이터는 기업, 정부, 개인에게 다양한 가치 창출을 가져다줌. 개인은 맞춤형 서비스와 적시에 필요한 정보를 얻음으로써 기회비용을 절약. 기업은 비즈니스 모델을 혁신하거나 신사업 발굴에 활용할 수 있게 됨. 산업 전체의 생산성도 향상됨. </p>\n<p>그러나 기업활동의 투명성이 없어지는 것은 빅데이터의 가치 창출 영향과는 달라서 옳지 않음. 빅데이터는 기업과 개인의 의사소통과 투명성을 높여야 하며, 기업은 빅데이터를 활용하여 경쟁력을 확보해야 하지만 투명성이 없어져서는 안됨.</p>"]},"rate":90,"rateN":3827},{"id":"62188","number":3,"category":"데이터 이해","type":"choice","subject":"사생활 침해 문제를 해결하기 위한 방법으로 가장 적절한 것은 무엇인가?","choices":[{"n":1,"html":"개인정보 사용자 책임제로 전환"},{"n":2,"html":"결과기반 책임 원칙 고수"},{"n":3,"html":"알고리즘 접근 허용"},{"n":4,"html":"사용자 동의제도 시행"}],"answer":[1],"explain":{"ai":["<p>사생활 침해 문제를 해결하기 위해 개인정보 사용자 책임제로 전환하는 것이 가장 적절한 방법이다. 이는 사용자가 자신의 개인정보를 어떻게 사용하고 관리할지를 스스로 책임지도록 함으로써 사생활 침해를 예방할 수 있다. </p>\n<p>사용자 동의제도는 개인정보를 사용하기 전에 사용자의 동의를 얻는 제도이다. 하지만 사용자가 unserem 개인정보가 어떻게 사용되고 있는지 정확히 알지 못하는 경우가 많기 때문에 사생활 침해를 완전히 예방할 수는 없다. </p>\n<p>결과기반 책임 원칙은 결과에 따라 책임을 부과하는 원칙이다. 하지만 사생활 침해의 경우 결과가 발생하기 전에 예방하는 것이 더 중요하다. </p>\n<p>알고리즘 접근 허용은 알고리즘이 어떻게 작동하는지 사용자가 이해할 수 있도록 하는 것이다. 하지만 알고리즘 자체가 사생활 침해의 원인이 된 경우에는 이 방법만으로는 해결할 수 없다. </p>\n<p>따라서 사생활 침해 문제를 해결하기 위해 가장 적절한 방법은 개인정보 사용자 책임제로 전환하는 것이다.</p>"]},"rate":75,"rateN":4297},{"id":"62189","number":4,"category":"데이터 이해","type":"choice","subject":"암묵지와 형식지 상호작용의 과정 중 개인의 내재된 경험을 객관적인 데이터로 변환하여 문서나 매체에 저장.가공.분석하는 과정을 무엇이라고 하는가?","choices":[{"n":1,"html":"표출화"},{"n":2,"html":"연결화"},{"n":3,"html":"내재화"},{"n":4,"html":"공통화"}],"answer":[1],"explain":{"ai":["<p>암묵지와 형식지의 상호작용 과정에서 중요한 개념이 있다. 암묵지는 개인이 가지고 있는 내재된 경험과 지식을 말한다. 이 암묵지를 객관적인 데이터로 변환하여 문서나 매체에 저장, 가공, 분석하는 과정을 표출화라고 한다. 이는 개인의 경험과 지식을 외부로 표현하여 공유하고 분석할 수 있도록 하는 महत्वप가지 과정이다. 이 과정을 통해 개인의 지식과 경험을 공유하고 분석할 수 있기 때문에 매우 중요하다. 따라서 정답은 1번인 표출화이다.</p>"]},"rate":74,"rateN":4493},{"id":"62190","number":5,"category":"데이터 이해","type":"choice","subject":"다음 비식별화 기법에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"가명처리는 식별할 수 없는 다른 값으로 대체를 의미한다."},{"n":2,"html":"데이터 마스킹은 개인 정보 식별이 가능한 특정 값을 삭제하는 것이다."},{"n":3,"html":"범주화는 단일 식별 정보 해당 그룹의 대푯값으로 변환을 한다."},{"n":4,"html":"총계처리는 총합 또는 평균값으로 대체하여 개별 데이터의 값이 보이지 않도록 하는 것이다."}],"answer":[2],"explain":{"ai":["<p>데이터 마스킹은 개인 정보 식별이 가능한 특정 값을 삭제 대신 일부를隐藏하는 것이다. \n가명처리는 식별할 수 없는 다른 값으로 대체를 의미하고 \n범주화는 단일 식별 정보 해당 그룹의 대푯값으로 변환을 하며 \n총계처리는 총합 또는 평균값으로 대체하여 개별 데이터의 값이 보이지 않도록 하는 것이다. \n따라서 데이터 마스킹 설명이 잘못되어 2번이 정답이다.</p>"]},"rate":63,"rateN":4739},{"id":"62191","number":6,"category":"데이터 이해","type":"choice","subject":"데이터베이스에 대한 설명으로 적절하지 않은 것은?","choices":[{"n":1,"html":"한 조직의 다수 사용자가 공동으로 이용하고 유지하는 공용데이터이다."},{"n":2,"html":"DBMS 소프트웨어를 사용하여 데이터베이스를 구축한다."},{"n":3,"html":"법률적으로 데이터베이스는 기술을 기반으로 한 일종의 저작물로 인정한다."},{"n":4,"html":"데이터베이스내의 모든 데이터는 2차원 테이블로 표현된다."}],"answer":[4],"explain":{"ai":["<p>데이터베이스의 특성 중에서 적절하지 않은 설명은 4번입니다. 데이터베이스는 데이터를 효율적으로 관리하기 위한 시스템으로, 다양한 구조와 모델을 지원합니다. 특히, 모든 데이터가 단순히 2차원 테이블로만 표현된다는 설명은 부정확합니다. 데이터베이스는 관계형 모델(2차원 테이블 기반)뿐만 아니라, NoSQL 데이터베이스와 같은 비관계형 모델들도 포함하며, 이들은 문서형, 키-값 쌍, 그래프형 등 다양한 형태를 가질 수 있습니다. 따라서 모든 데이터가 2차원 테이블로만 제한적으로 표현된다는 것은 정확하지 않습니다.</p>"]},"rate":79,"rateN":4116},{"id":"62192","number":7,"category":"데이터 이해","type":"choice","subject":"데이터웨어하우스에 대한 설명으로 가장 적절하지 않은 것은 무엇인가?","choices":[{"n":1,"html":"ETL은 주기적으로 내부 및 외부 데이터베이스로부터 정보를 추출하고 정해진 규약에 따라 정보를 변환한 후에 데이터웨어하우스에 정보를 적재한다."},{"n":2,"html":"데이터웨어하우스는 전사적 차원보다는 특정 조직의 특정 업무 분야에 초점을 둔 것이다."},{"n":3,"html":"데이터웨어하우스에서 관리하는 데이터들은 시간적 흐름에 따라 변화하는 값을 유지한다."},{"n":4,"html":"데이터웨어하우스는 기업 내의 의사결정 지원 애플리케이션을 위한 정보를 제공하는 하나의 통합된 데이터 저장 공간을 말한다."}],"answer":[2],"explain":{"ai":["<p>데이터웨어하우스는 기업 내의 의사결정 지원을 위한 정보를 제공하는 통합된 데이터 저장 공간이다. 데이터웨어하우스는 전사적 차원에서 다양한 업무 분야의 정보를 통합적으로 관리하기 위한 것이다. 그렇기 때문에 특정 조직이나 업무 분야에만 초점을 둔 것이 아니라 전사적 차원에서 데이터를 관리한다. 따라서 데이터웨어하우스에 대한 설명으로 가장 적절하지 않은 것은 전사적 차원보다는 특정 조직의 특정 업무 분야에 초점을 둔 것이다. </p>\n<p>이것은 데이터웨어하우스의 정의에 부합하지 않기 때문에 데이터웨어하우스에 대한 설명으로는 적절하지 않다. 반면에 ETL을 통해 정보를 추출하고 변환하여 데이터웨어하우스에 적재하는 프로세스나 데이터웨어하우스에서 관리하는 데이터가 시간적 흐름에 따라 변화하는 값을 유지하는 것은 데이터웨어하우스의 특징이다.</p>"]},"rate":77,"rateN":4069},{"id":"62193","number":8,"category":"데이터 이해","type":"choice","subject":"다음 데이터 사이언스에 대한 설명으로 가장 부적절한 것은?","choices":[{"n":1,"html":"데이터 사이언스란 데이터로부터 의미있는 정보를 추출해내는 학문이다."},{"n":2,"html":"분석 뿐 아니라 이를 효과적으로 구현하고 전달하는 과정까지 포함한 포괄적 개념이다."},{"n":3,"html":"정형 데이터를 대상으로 총체적 접근법을 사용한다."},{"n":4,"html":"과학과 인문학의 교차로에 서 있다고 할 수 있다."}],"answer":[3],"explain":{"ai":["<p>데이터 사이언스란 데이터로부터 의미있는 정보를 추출해내는 학문이다. 데이터 사이언스는 분석뿐 아니라 이를 효과적으로 구현하고 전달하는 과정까지 포함한 포괄적 개념이다. 데이터 사이언스는 다양한 영역의 지식을 결합한 분야로 과학과 인문학의 교차로에 있다고 할 수 있다.</p>\n<p>그러나 데이터 사이언스에서 정형 데이터만을 대상으로 하거나 총체적 접근법만을 사용하는 것은 아니다. 데이터 사이언스는 정형 데이터뿐 아니라 비정형 데이터도 처리하고 다양한 관련 기술을 사용하여 데이터를 분석한다. 따라서 정형 데이터를 대상으로 총체적 접근법을 사용한다는 설명은 가장 부적절하다.</p>"]},"rate":84,"rateN":3935},{"id":"62194","number":9,"category":"데이터 이해","type":"choice","subject":"다음 중 기업의 데이터 분석 도입의 수준 진단의 대상으로 가장 적절하지 않은 것?","choices":[{"n":1,"html":"분석 업무 파악"},{"n":2,"html":"분석 기법"},{"n":3,"html":"분석 인력 및 조직"},{"n":4,"html":"분석 성과 평가"}],"answer":[4],"explain":{"ai":["<p>데이터 분석 도입의 수준 진단은 현재 기업의 데이터 분석 능력과 상태를 평가하여 향후 필요한 개선 점을 파악하는 것을 목적으로 합니다. 따라서, 이 진단의 대상은 주로 데이터 분석을 수행하는 데 필요한 자원과 구성 요소에 초점을 맞추게 됩니다.</p>\n<ol>\n<li>\n<p>분석 업무 파악: 이는 데이터 분석이 어떤 업무와 관련되어 있는지, 어떤 문제를 해결하기 위해 분석이 사용되는지 파악하는 것입니다. 이러한 파악은 데이터 분석의 범위와 필요성을 이해하는 데 도움이 됩니다.</p>\n</li>\n<li>\n<p>분석 기법: 사용되는 분석 기법의 유형과 수준을 평가합니다. 이는 데이터 분석의 깊이와 복잡성을 측정하는 데 도움이 됩니다.</p>\n</li>\n<li>\n<p>분석 인력 및 조직: 데이터 분석을 수행하는 인력의 역량과 조직 구조를 평가합니다. 이는 데이터 분석을 수행하는 데 필요한 인적 자원과 조직적인 지원의 수준을 파악하는 데 중요합니다.</p>\n</li>\n<li>\n<p>분석 성과 평가: 이는 데이터 분석이 가져온 성과를評価하는 것입니다. 분석 성과는 이미 이루어진 분석 활동의 결과를 측정하는 것으로,enterprise의 데이터 분석 도입 수준을 진단할 때는 아직 이루어지지 않은 부분이나 잠재력을 평가하는 데보다는 이미 이루어진 분석 성과를 측정하는 데 더に関係가 있습니다.</p>\n</li>\n</ol>\n<p>따라서, 기업의 데이터 분석 도입의 수준 진단의 대상으로 가장 적절하지 않은 것은 이미 이루어진 성과를 평가하는 4번 분석 성과 평가입니다. 데이터 분석 도입의 수준 진단은 미래의 데이터 분석 능력을 향상시키기 위한 기초를 다지는 데 중점을 둔 것으로, 현재의 상태와 자원을 평가하여 향후의 계획을 수립하는 데 사용됩니다.</p>"]},"rate":67,"rateN":4673},{"id":"62195","number":10,"category":"데이터 이해","type":"choice","subject":"분석 성숙도 모델 구성에서 고려하는 분석 성숙도 진단 부문으로 적절하지 않은 것은?","choices":[{"n":1,"html":"비즈니스 부문"},{"n":2,"html":"기업 문화 부문"},{"n":3,"html":"조직의 역량 부문"},{"n":4,"html":"IT 부문"}],"answer":[2],"explain":{"ai":["<p>데이터분석 준전문가 시험의 '데이터 이해' 과목에서 분석 성숙도 모델 구성의 분석 성숙도 진단 부문을 묻는 문제입니다. 분석 성숙도 모델은 조직의 데이터 분석 능력을 평가하고 개선하는 프레임워크입니다. 이 모델의 구성 요소 중 분석!=( 진단 부문은 주로 조직의 데이터 분석 역량을 평가하기 위한 것입니다.</p>\n<p>분석 성숙도 진단 부문은 일반적으로 조직의 데이터 분석 능력을 평가하는 다음과 같은 부분을 포함합니다.</p>\n<ul>\n<li>비즈니스 부문: 데이터가 비즈니스 목표에 어떻게 기여하는지 평가합니다.</li>\n<li>IT 부문: 데이터 분석을 위한 기술 인프라와 시스템을 평가합니다.</li>\n<li>조직의 역량 부문: 데이터 분석에 필요한 인력과 기술력을 평가합니다.</li>\n</ul>\n<p>그러나 '기업 문화 부문'은 분석 성숙도 모델의 핵심 진단 부문은 아닙니다. 기업 문화는 분석 성숙도에 영향을 미치지만, 분석 성숙도 모델의 주요 구성 요소는 아닙니다. 따라서 이 문제의 정답은 2번 '기업 문화 부문'입니다. 이는 분석 성숙도 모델의 핵심적인 진단 영역이 아니기 때문입니다.</p>"]},"rate":58,"rateN":5084},{"id":"62196","number":11,"category":"데이터 분석 기획","type":"choice","subject":"다음 분석과제의 특징 중 Accuracy와 Precision에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"분석의 활용적인 측변에서는 Precision이 중요하며, 안정적인 측면에서는 Accuracy가 중요하다."},{"n":2,"html":"Accuracy와 Precision의 관계는 트레이드 오프가 되는 경우가 많다."},{"n":3,"html":"Accuracy는 모델과 실제 값의 차이에 대한 것이다."},{"n":4,"html":"Precision은 모델을 반복했을 때의 편차를 의미한다."}],"answer":[1],"explain":{"ai":["<p>Precision은 모델의 안정성과 관련이 있으며, Accuracy는 모델의 활용적인 측면과 관련이 있습니다. 따라서 1번은 설명이 틀렸습니다. Accuracy는 모델의 성능을 평가하는 데 사용되며,Accuracy는 모델과 실제 값의 차이에 대한 것입니다. Precision은 모델이 동일한 결과를 반복할 수 있는지에 대한 것입니다.TRAIN Fransız 과정에서 모델의 안정성을 평가하기 위해 Precision을 사용하는 경우가 많습니다.</p>"]},"rate":61,"rateN":4640},{"id":"62197","number":12,"category":"데이터 분석 기획","type":"choice","subject":"다음 중 분석 대상은 명확하지만 분석 방식이 명확하지 않은 경우 수행하는 분석 주제의 유형은 무엇인가?","choices":[{"n":1,"html":"솔루션(Solution)"},{"n":2,"html":"통찰(Insight)"},{"n":3,"html":"최적화(Optimization)"},{"n":4,"html":"발견(Discovery)"}],"answer":[1],"explain":{"ai":["<p>분석 대상이 명확하지만 분석을 통해 어떤 방향으로 접근하거나 해결해야 할지 방법론이 불분명한 상황에서는 <strong>솔루션(Solution)</strong> 유형의 분석 주제를 수행하게 됩니다. 이 유형은 구체적인 문제나 대상에 초점을 맞추지만, 그 해결 방안이나 분석 방법론이 아직 정의되지 않은 상태에서 다양한 접근법을 탐색하고 최적의 해결 방안을 찾는 과정을 포함합니다. 다른 옵션들과 비교했을 때:</p>\n<ul>\n<li><strong>통찰(Insight)</strong>: 주로 데이터 내 숨겨진 패턴이나 의미를 이해하는 데 중점을 둡니다.</li>\n<li><strong>최적화(Optimization)</strong>: 이미 정해진 목표를 달성하기 위한 가장 효율적인 방법을 찾는 데 초점을 맞춥니다.</li>\n<li><strong>발견(Discovery)</strong>: 새로운 지식이나 패턴을 탐색하는 데 중점을 두지만, 여기서는 분석 방식의 명확성 부족이 주요 특징으로 명시되어 있어 적합하지 않습니다.</li>\n</ul>\n<p>따라서 분석 방식이 명확하지 않은 상황에서 여러 가능성을 탐색하며 해결책을 도출하는 <strong>솔루션(Solution)</strong>이 정답입니다.</p>"]},"rate":76,"rateN":4057,"exWarn":["doubt"]},{"id":"62198","number":13,"category":"데이터 분석 기획","type":"choice","subject":"분석 과제 정의서에 대한 설명으로 가장 적절한 것은 무엇인가?","choices":[{"n":1,"html":"프로젝트 수행 계획 수립 단계에서 전체 업무를 분류하여 구성 요소로 만든 후 각 요소를 평가하고 일정별로 계획하며 그것을 완수할 수 있는 사람에게 할당해주는 역할을 한다."},{"n":2,"html":"분석 모델에 적용될 알고리즘과 분석모델의 기반이 되는 Feature가 포함되어야 한다."},{"n":3,"html":"이해관계자가 프로젝트의 방향을 설정하고, 성공 여부를 판별할 수 없는 자료이다."},{"n":4,"html":"필요한 소스 데이터, 분석 방법, 데이터 입수 난이도, 분석 과정 상세 등의 항목이 포함되어야 한다."}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. \n분석 과제 정의서에는 분석의 목적, 범위, 대상 데이터, 분석 방법, 소요 시간, 예상 결과 등의 정보가 포함되어야 하며, 4번의 내용인 프로젝트의 필요 소스 데이터, 분석 방법, 데이터 입수 난이도, 분석 과정 상세 등의 항목이 포함되어야 한다는 설명이 가장 적절합니다. \n이러한 정보는 분석 과제의 범위와 목표를 명확하게 정의하고, 분석을 수행하는 데 필요한 자원과 시간을 예상하는 데 도움이 됩니다. \n따라서 4번이 가장 적절한 설명입니다.</p>"]},"rate":52,"rateN":4833},{"id":"62199","number":14,"category":"데이터 분석 기획","type":"choice","subject":"분석 마스터 플랜을 수립할 때 적용 범위 및 방식에 대한 고려요소가 아닌 것은 무엇인가?","choices":[{"n":1,"html":"투입 비용 수준"},{"n":2,"html":"분석 데이터 적용 수준"},{"n":3,"html":"업무 내재화 적용 수준"},{"n":4,"html":"기술 적용 수준"}],"answer":[1],"explain":{"ai":["<p>분석 마스터 플랜 수립 시 적용 범위와 방식을 결정하는 데 직접적인 영향을 미치지 않는 요소는 <strong>투입 비용 수준</strong>입니다 (1번). </p>\n<p>투입 비용은 계획 실행 후의 예산 관리 및 효율성 평가에 중요하지만, 초기 마스터 플랜 단계에서 분석의 실제 적용 범위 (데이터 종류와 양 <2>), 내부 업무 프로세스 통합 정도 <3>, 그리고 사용할 기술의 적합성 <4>에 비해 직접적인 범위 및 방식 결정 요소로는 적합하지 않습니다. 따라서 정답은 1번입니다.</p>"]},"rate":59,"rateN":4721},{"id":"62200","number":15,"category":"데이터 분석 기획","type":"choice","subject":"분석 마스터플랜의 세부 이행계획 수립 시 고려해야 할 데이터 분석 체계에 대한 설명으로 적절한 것은?","choices":[{"n":1,"html":"분석  마스터플랜의 모든 단계를 반복한다."},{"n":2,"html":"프로젝트의 세부 일정계획도 데이터 분석체계를 고려하여 작성한다."},{"n":3,"html":"순차적인 정련 과정을 통해 프로젝트의 기간을 단축하는 방식을 주로 사용한다."},{"n":4,"html":"데이터 수집 및 확보와 분석 데이터를 준비하는 단계를 반복적으로 진행한다."}],"answer":[2],"explain":{"ai":["<p>분석 마스터플랜의 세부 이행계획 수립 시 고려해야 할 데이터 분석 체계를 설명하는 문제입니다. \n정답은 2번 \"프로젝트의 세부 일정계획도 데이터 분석체계를 고려하여 작성한다\"입니다. \n이 이유는 데이터 분석 체계가 프로젝트의 성공을 결정짓는 중요한 요소이기 때문입니다. \n데이터 분석체계를 고려하여 세부 일정계획을 작성하면, 데이터 수집, 분석, 및 결과 도출 등 모든 단계에서 데이터의 품질과 일관성을 보장할 수 있습니다. \n또한, 데이터 분석체계를 고려하여 작성된 세부 일정계획은 프로젝트의 기간과 비용을 효율적으로 관리할 수 있도록 도와줍니다. \n따라서, 분석 마스터플랜의 세부 이행계획 수립 시에는 데이터 분석체계를 고려하여 작성하는 것이 중요합니다.</p>"]},"rate":58,"rateN":4558},{"id":"62201","number":16,"category":"데이터 분석 기획","type":"choice","subject":"분석 기획에 대한 설명으로 적절하지 않은 것은 무엇인가?","choices":[{"n":1,"html":"해당 문제 영역에 대한 전문성 역량 및 통계학적 지식을 활용한 분석 역량과 분석 도구인 데이터 및 프로그래밍 기술 역량에 대한 균형 잡힌 시각을 가지고 방향성 및 계획을 수립해야 한다."},{"n":2,"html":"성공적인 분석을 하기 전 중요 사전 작업이다."},{"n":3,"html":"상향식 분석은 분석 기획 전 탐색적 데이터 분석 수행을 한다."},{"n":4,"html":"실제 분석을 수행에 앞서 분석을 수행할 과제의 정의 및 의도했던 결과를 도출할 수 있도록 이를 적절하게 관리할 수 있는 방안을 사전에 계획하는 일련의 작업이다."}],"answer":[3],"explain":{"ai":["<p>분석 기획은 데이터 분석 프로젝트의 성공을 위해 사전 작업을 수행하는 과정입니다._analysis 기획의 정의와 중요성을 설명하는 보기 중에서 적절하지 않은 설명은 3번입니다.</p>\n<p>3번은 상향식 분석을 설명하며, 분석 기획 전 탐색적 데이터 분석을 수행한다고 합니다. 하지만, 분석 기획은 프로젝트의 목표와 범위를 정의하고, 필요한 데이터와 분석 방법을 계획하는 과정입니다. 상향식 분석은 분석 기획의 일부로, 기획 단계에서 수행하는 것이 아니라 실제 분석을 수행하는 단계에서 수행됩니다.</p>\n<p>따라서, 분석 기획에 대한 설명으로 적절하지 않은 것은 3번입니다. 다른 보기들은 분석 기획의 중요성과 과정을 잘 설명하고 있습니다. 특히, 1번은 분석 기획의 전문성과 기술 역량에 대한 균형 잡힌 시각을 강조하며, 2번과 4번은 분석 기획의 중요성과 프로젝트의 성공을 위한 사전 작업을 강조합니다.</p>"]},"rate":75,"rateN":3914},{"id":"62352","number":17,"category":"데이터 분석 기획","type":"choice","subject":"빅데이터의 4V는 빅데이터의 3V에 무엇이 추가된 것인가?","choices":[{"n":1,"html":"Volume"},{"n":2,"html":"Value"},{"n":3,"html":"Variety"},{"n":4,"html":"Velocity"}],"answer":[2],"explain":{"ai":["<p>빅데이터의 3V는 데이터의 양, 종류, 속도를 의미합니다. 빅데이터의 4V는 3V에 데이터의 가치 즉 값이 추가된 것입니다. 데이터의 가치를 값이라고 하며 이는 데이터가 가지는 유용성이나重要성을 나타냅니다. 즉 데이터의 크기와 속도 그리고 다양성 외에 데이터가 가져오게 되는 결과물의 유용성이 Values입니다. 따라서 정답은 2번입니다.</p>"]},"rate":84,"rateN":3635},{"id":"62353","number":18,"category":"데이터 분석 기획","type":"choice","subject":"다음 빈칸에 공통으로 들어갈 단어로 알맞은 것은 무엇인가?","extra":"<pre class=\"contents\">분석 과제 우선순위 평가 기준에는 (   )과 난이도가 있으며 (   )의 경우 전략적 중요도와 목표가치, 난이도의 경우 데이터 획득/저장/가공 비용, 분석 적용 비용, 분석 수준에 따라 판단하게 된다.</pre>","choices":[{"n":1,"html":"시급성"},{"n":2,"html":"안정성"},{"n":3,"html":"활용성"},{"n":4,"html":"희귀성"}],"answer":[1],"explain":{"ai":["<p>빈칸에 들어갈 단어는 시급성이다. 분석 과제 우선순위 평가 기준에는 시급성과 난이도가gle 있다. 시급성은 전략적 중요도와 목표가치에 따라 판단하고 난이도는 데이터 획득이나 저장이나 가공 비용, 분석 적용 비용, 분석 수준에 따라 판단한다. 시급성은 분석이 얼마나 빠르게 이루어져야 하는지에 대한 것을 의미한다. 분석이 긴급하게 필요한 경우는 시급성이 높은 편이며 반대로 분석이 긴급하지 않다면 시급성이 낮은 편이다. 따라서 분석과제를 평가하고 우선순위를 정할 때 시급성은 중요한 평가 기준이 된다.</p>"]},"rate":91,"rateN":3279},{"id":"62354","number":19,"category":"데이터 분석 기획","type":"choice","subject":"다음 중 군집분석 기법으로 적절하지 않은 것은 무엇인가?","choices":[{"n":1,"html":"PAM"},{"n":2,"html":"DBSCAN"},{"n":3,"html":"실루엣 지수(Silhouette Coefficient)"},{"n":4,"html":"퍼지(Fuzzy) Clustering"}],"answer":[3],"explain":{"ai":["<p>군집분석 기법은 데이터를 군집으로 분류하는 방법으로, 여러 기법이 있습니다. PAM(Partitioning Around Medoids), DBSCAN(Density-Based Spatial Clustering of Applications with Noise), 퍼지 클러스터링(Fuzzy Clustering) 등은 모두 군집분석 기법입니다. </p>\n<p>실루엣 지수(Silhouette Coefficient)는 군집분석의 결과를 평가하는 지표로, 각 데이터 포인트가 속한 군집과 가장 가까운 다른 군집 사이의 거리를 계산하여 군집의 분리度와 응집도를 평가합니다. 즉, 군집분석의 결과를 평가하는 데 사용되는 지표이지, 군집분석 기법 자체가 아닙니다. </p>\n<p>따라서, 군집분석 기법으로 적절하지 않은 것은 실루엣 지수(Silhouette Coefficient)이며, 정답은 3번입니다.</p>"]},"rate":51,"rateN":4776},{"id":"62355","number":20,"category":"데이터 분석 기획","type":"choice","subject":"Wage 데이터셋에 대한 anova 분석 결과 해석의 내용 중 틀린 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"age와 wage에 대한 선형관계를 알 수 없다."},{"n":2,"html":"age와 wage는 양의 상관관계이다."},{"n":3,"html":"관측치는 3000 개 이다."},{"n":4,"html":"MSE는 1675 이다."}],"answer":[2],"rate":44,"rateN":5430},{"id":"62356","number":21,"category":"데이터 분석","type":"choice","subject":"웹 데이터의 수집을 위해 웹페이지의 구조를 분석하여 데이터를 자동으로 수집하는 방법을 무엇이라고 하는가?","choices":[{"n":1,"html":"FTP"},{"n":2,"html":"웹 크롤링(Web Crawling)"},{"n":3,"html":"Streaming"},{"n":4,"html":"Open API"}],"answer":[2],"explain":{"ai":["<p>웹 데이터의 자동 수집 방법 중에서 웹페이지의 구조를 분석하고 필요한 정보를 체계적으로 탐색하며 모으는 기법을 묻는 문제입니다. </p>\n<p><code>FTP</code>는 파일 전송 프로토콜로 파일 공유에 주로 사용됩니다. <code>Streaming</code>은 실시간 데이터 전송을 의미하며, 주로 미디어 콘텐츠의 실시간 재생에 관련됩니다. <code>Open API</code>는 특정 서비스나 데이터에 접근하기 위한 공개된 인터페이스를 제공하지만, 수동적인 데이터 요청 방식에 더 가깝습니다.</p>\n<p><code>웹 크롤링(Web Crawling)</code>, 즉 정답인 2번은 소프트웨어 로봇이 웹사이트를 자동으로 순회하며 필요한 데이터를 수집하는 과정을 말합니다. 이 방법은 정규표현식, HTML 파싱 등 다양한 기술을 활용해 웹페이지의 구조를 분석하고, 지정된 정보를 효과적으로 추출합니다. 따라서 웹 데이터를 자동화된 방식으로 대량 수집하는데 최적화된 기술이 바로 웹 크롤링입니다.</p>"]},"rate":92,"rateN":3019},{"id":"62357","number":22,"category":"데이터 분석","type":"choice","subject":"신경망 모형에서 출력값이 여러 개이고 목표치가 다범주인 경우에 사용하는 것으로 각 범주에 속할 사후 확률을(posterior probability) 제공하는 활성화 함수는 무엇인가?","choices":[{"n":1,"html":"항등 함수"},{"n":2,"html":"ReLU"},{"n":3,"html":"sigmoid"},{"n":4,"html":"softmax"}],"answer":[4],"explain":{"ai":["<p>다범주 분류 문제에서 각 클래스에 속할 확률을 출력하는 데 적합한 활성화 함수는 softmax 함수이다. softmax는 신경망의 출력층에서 사용되며, 여러 개의 출력 노드를 통해 얻은 선형 조합 값을 확률 분포로 변환한다. 이 함수는 각 출력 값을 0과 1 사이의 값으로 정규화하여 전체 합이 1이 되게 하며, 이로 인해 각 범주에 속할 사후 확률을 제공한다. 다른 옵션들과 비교했을 때:</p>\n<ul>\n<li>항등 함수는 입력 값을 그대로 출력하므로 확률 분포를 제공하지 않는다.</li>\n<li>ReLU는 주로 은닉층에서 사용되며, 양수 입력에 대해 그대로 출력하고 음수 입력에 대해 0을 출력하므로 분류 확률을 제공하지 않는다.</li>\n<li>sigmoid 함수는 이진 분류 문제에서 각 클래스에 속할 확률을 제공하지만, 여러 범주를 다루는 다범주 문제에서는 각 범주에 대한 독립적인 확률 분포를 제공하지 못한다.</li>\n</ul>\n<p>따라서, 다범주 분류 문제에서 각 범주에 속할 사후 확률을 제공하는 올바른 답은 <strong>softmax</strong>이다.</p>"]},"rate":52,"rateN":4366},{"id":"62358","number":23,"category":"데이터 분석","type":"choice","subject":"시그모이드 함수의 범위로 알맞은 것은?","choices":[{"n":1,"html":"0~1"},{"n":2,"html":"-1~1"},{"n":3,"html":"-1~0"},{"n":4,"html":"0.5~1"}],"answer":[1],"explain":{"ai":["<p>시그모이드 함수는 입력값이 아무리 작아도 0보다 크고, 아무리 커도 1보다 작은 값을 반환한다. 시그모이드 함수의 그래프는 S자 모양을 띄는데, 입력값이 무한대로 가면 출력값은 1에 가까워지고, 입력값이 마우 khổ스로 가면 출력값은 0에 가까워진다. 따라서 시그모이드 함수의 범위는 0과 1 사이로, 0과 1은 포함하지 않는다. 하지만 시그모이드 함수의 정의역과 공역을 고려해 보통 0에서 1까지로 간주한다. 따라서 시그모이드 함수의 범위로 알맞은 것은 0에서 1 사이이다.</p>"]},"rate":70,"rateN":3591},{"id":"62359","number":24,"category":"데이터 분석","type":"choice","subject":"다음의 수식에 해당하는 데이터 간의 거리 계산 방식은 무엇인가?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"유클리드 거리"},{"n":2,"html":"맨해튼 거리"},{"n":3,"html":"민코프스키 거리"},{"n":4,"html":"마할라노비스 거리"}],"answer":[2],"rate":66,"rateN":3813},{"id":"62360","number":25,"category":"데이터 분석","type":"choice","subject":"연관분석에 대한 특징 틀린 것은?","choices":[{"n":1,"html":"조건반응(if then)으로 표현되는 연관분석의 결과를 이해하기 쉽다."},{"n":2,"html":"비목적성 분석 기법이다."},{"n":3,"html":"대표적인 알고리즘으로 Aprior가 있다."},{"n":4,"html":"분석을 위한 계산이 복잡하다는 단점이 있다."}],"answer":[4],"explain":{"ai":["<p>연관분석은 데이터 내에 숨겨진 연관성이나 패턴을 발견하기 위한 기술입니다. 연관분석의 특징을 분석해 보면, </p>\n<ol>\n<li>조건과 결과를 if-then 형태로 표현하여 결과를 이해하기 쉽게 제공합니다. </li>\n<li>연관규칙의 도출을 위해 事前적으로 특정 목적이나 가설을 설정하지 않는 비목적성 분석 기법입니다.</li>\n<li>대표적인 연관분석 알고리즘으로 Apriori가 있습니다.</li>\n</ol>\n<p>이러한 특징에 비추어보면, \n4. 분석을 위한 계산이 복잡하다는 단점이 있습니다. 하지만 연관분석은 데이터의 규모와 복잡성에 따라 계산 복잡도가 증가할 수 있습니다. 하지만modern 컴퓨팅 파워와 효율적인 알고리즘의 발전으로 인해, 연관분석의 계산 복잡성은 많이 개선되었습니다. </p>\n<p>따라서, 연관분석의 특징 중에서 \"분석을 위한 계산이 복잡하다는 단점이 있다\"는 특징은 상대적으로 덜 정확한 표현입니다. 즉, 연관분석의 계산 복잡성은 데이터의 크기와 알고리즘의 효율성에 따라 달라질 수 있으므로, 이는 절대적인 단점이라고 말하기는 어렵습니다. </p>\n<p>따라서, 연관분석에 대한 특징 중에서 틀린 것은 4번입니다.</p>"]},"rate":59,"rateN":3912},{"id":"62361","number":26,"category":"데이터 분석","type":"choice","subject":"다음 중 표본들이 서로 관련되어 있는 경우, 짝지어진 두 개의 관찰치들의 크고 작음을 +와 -로 표시하여 그 개수를 가지고 두 그룹의 분포 차이가 있는가에 대한 가설을 검증하는 방법은 무엇인가?","choices":[{"n":1,"html":"Sign Test"},{"n":2,"html":"Chi-Square Test"},{"n":3,"html":"ANOVA Test"},{"n":4,"html":"스피어만 상관계수"}],"answer":[1],"explain":{"ai":["<p>결정적인 요소는 짝지어진 두 개의 관찰치에 있습니다. 짝지어진 두 개의 관찰치들의 크고 작음을 보여주는 기호를 이용해 두 그룹의 분포 차이를 가설 검증하는 방법은 Sign Test입니다. 짝지어진 표본은 서로 관련되어 있습니다. 짝지어진 두 개의 관찰치의 크고 작음을 +와 -로 표시하여 그 개수를 가지고 두 그룹의 분포 차이가 있는지를 검증하기 위해 사용하는 통계 방법이 Sign Test입니다.</p>"]},"rate":45,"rateN":4743},{"id":"62362","number":27,"category":"데이터 분석","type":"choice","subject":"자료의 척도에 대한 설명으로 적절하지 않은 것은?","choices":[{"n":1,"html":"비율척도 - 사칙연산이 모두 가능하고, 혈액형, 학력 등이 해당된다."},{"n":2,"html":"구간척도 - 덧셈, 뺄셈이 가능하고 절대 0점을 포함하지 않는 온도가 이에 해당된다."},{"n":3,"html":"서열척도 - 연산이 불가능하고 메달과 같이 범주간 순서가 있는 것이 이에 해당된다."},{"n":4,"html":"명목척도 - 단순히 측정 대상의 특성을 분류하거나 확인하기 위한 목적으로 사용된다."}],"answer":[1],"explain":{"ai":["<p>자료의 척도는 크게 4가지로 나뉘는데 비율척도, 구간척도, 서열척도, 명목척도이다. \n명목척도는 분류나 확인을 위한 목적으로 사용되며 연산이 불가능하다. \n서열척도는 순서가 있으나 연산은 불가능하다. \n구간척도는 덧셈과 뺄셈이 가능하지만 숫자間의 간격은 일정하不过 절대 0점은 없다. \n비율척도는 모든 연산이 가능하고 절대 0점이 존재한다. \n따라서 비율척도에서 사칙연산이 모두 가능하고 혈액형, 학력이 해당된다고 설명한 것은 적절하지 않다. \n왜냐하면 혈액형이나 학력은 절대 0점의概念이 없으며 단순 분류나 확인을 위한 목적으로 사용되기 때문이다.</p>"]},"rate":67,"rateN":3734},{"id":"62363","number":28,"category":"데이터 분석","type":"choice","subject":"소득순위처럼 정규분포가 아닌 오른쪽 꼬리가 긴 분포(Positive skewed)에서 평균과 중앙값의 관계로 알맞은 것은?","choices":[{"n":1,"html":"중앙값이 평균보다 크다"},{"n":2,"html":"평균이 중앙값보다 크다"},{"n":3,"html":"평균과 중앙값의 관계에 변화가 없다"},{"n":4,"html":"평균은 중앙값의 제곱과 같다"}],"answer":[2],"explain":{"ai":["<p>오른쪽 꼬리가 긴 분포, 즉 양의 왜도를 가진 데이터에서는 극단적으로 높은 값들이 평균을 상승시킵니다. 이로 인해 중앙값이 전체 데이터의 중앙 위치를 더 안정적으로 나타내는 반면, 평균은 이러한 극단값의 영향을 크게 받습니다. 따라서 평균은 중앙값보다 높게 나타나게 됩니다. 정답은 2번, \"평균이 중앙값보다 크다\"입니다.</p>"]},"rate":73,"rateN":3476},{"id":"62364","number":29,"category":"데이터 분석","type":"choice","subject":"R에서 숫자형, 문자형, 논리형 벡터를 하나로 합친 벡터를 구성하는 경우 합쳐진 벡터의 형식은 무엇인가?","choices":[{"n":1,"html":"숫자형 벡터"},{"n":2,"html":"문자형 벡터"},{"n":3,"html":"논리형 벡터"},{"n":4,"html":"데이터프레임"}],"answer":[2],"explain":{"ai":["<p>R에서 숫자형, 문자형, 논리형 벡터를 하나로 합친 벡터를 구성하면, 합쳐진 벡터의 형식은 문자형 벡터가 된다.这是因为 R에서 여러 유형의 데이터를 하나의 벡터로 결합할 때, 벡터의 모든 요소가 같은 유형이어야 하는데, 문자형이 가장 포괄적인 형식이기 때문이다. 따라서 다른 유형의 데이터를 문자형으로 강제 형변환하여 하나의 벡터로 합친다.</p>"]},"rate":48,"rateN":4597},{"id":"62365","number":30,"category":"데이터 분석","type":"choice","subject":"다음 중 빅데이터 분석 프로세스에서 모델링 단계에 해당하지 않는 항목은 무엇인가?","choices":[{"n":1,"html":"데이터 분할"},{"n":2,"html":"데이터 모델링"},{"n":3,"html":"모델 적용 및 운영 방안"},{"n":4,"html":"수행방안 설계"}],"answer":[4],"explain":{"ai":["<p>모델링 단계는 빅데이터 분석 프로세스에서 주로 데이터를 기반으로 예측 모델을 생성하고 평가하는 과정을 포함한다. 이 단계 내에서 주로 다루는 항목들은 다음과 같다:</p>\n<ol>\n<li><strong>데이터 분할</strong> - 학습 데이터와 검증 데이터로 나누는 작업으로, 모델의 성능을 정확히 평가하는 데 필요하다.</li>\n<li><strong>데이터 모델링</strong> - 실제로 분석 모델을 설계하고 학습시키는 과정이다.</li>\n<li><strong>모델 적용 및 운영 방안</strong> - 학습된 모델을 실제 환경에 적용하고 유지 관리하는 전략을 세우는 단계로, 모델링의 연장선상에 있다.</li>\n</ol>\n<p>반면, <strong>4. 수행방안 설계</strong>는 분석 프로젝트 전반의 계획 단계에 더 가깝다. 이는 데이터 수집부터 분석 목표 설정, 사용할 기법 선택 등 프로젝트 초기 단계에서 이루어지는 전략적 결정을 포함한다. 따라서 모델링 단계와 직접적인 관련이 없다.</p>\n<p>따라서 정답은 4번이다.</p>"]},"rate":52,"rateN":4313},{"id":"62366","number":31,"category":"데이터 분석","type":"choice","subject":"다음 중 모형 성과 평가 방법으로 적절하지 않은 것은?","choices":[{"n":1,"html":"결정계수"},{"n":2,"html":"실루엣 지수"},{"n":3,"html":"엔트로피(Entropy)"},{"n":4,"html":"ROC 그래프"}],"answer":[3],"explain":{"ai":["<p>모형 성과 평가 방법은 모델의 성능을 평가하는 데 사용된다. 결정계수는 모델의 설명력과 예측 성능을 평가하는 데 사용되며, 실루엣 지수는 클러스터링 모델의 성능을 평가하는 데 사용된다. ROC 그래프는 분류 모델의 성능을 평가하는 데 사용된다. </p>\n<p>엔트로피는 정보이론에서 정보의 불확실성을 측정하는 데 사용되며,_ORDαιο 모델의 성능 평가에 직접적으로 사용되지는 않는다. 엔트로피는 모델의 Complexity나 정보 이론적 특성을 평가하는 데 사용될 수 있지만, 성능 평가 방법으로는 적절하지 않다. 따라서 모형 성과 평가 방법으로 적절하지 않은 것은 엔트로피이다.</p>"]},"rate":52,"rateN":4367},{"id":"62367","number":31,"category":"데이터 분석","type":"choice","subject":"다음 중 분류 모형 평가에 활용하지 않는 것은 무엇인가?","choices":[{"n":1,"html":"덴드로그램"},{"n":2,"html":"오분류표"},{"n":3,"html":"ROC 그래프"},{"n":4,"html":"Kappa 지수"}],"answer":[1],"explain":{"ai":["<p>분류 모형 평가에는 다양한 방법이 활용된다. 오분류표는 실제 클래스와 예측 클래스를 비교하여 평가하는 표이다. ROC 그래프는 분류 모형의 성능을 평가하는 그래프로 TRUE Positive Rate와 FALSE Positive Rate를 그래프로 표현한다. Kappa 지수는 평가자 간의 일치도를 측정하는 지수로 분류 모형의 성능을 평가하는 데에도 사용된다. </p>\n<p>그러나 덴드로그램은 계층적 군집 분석에서 사용되는 그래프로 분류 모형의 평가에는 사용되지 않는다. 덴드로그램은 데이터를 군집화하여 계층 구조를 나타내는데 사용된다. 따라서 분류 모형 평가에 활용하지 않는 것은 덴드로그램이다.</p>"]},"rate":54,"rateN":2525},{"id":"62368","number":32,"category":"데이터 분석","type":"choice","subject":"다차원척도법에 대한 설명으로 가장 적절하지 않은 것은 무엇인가?","choices":[{"n":1,"html":"개체들의 거리는 유클리드(Euclidean) 거리와 유사도를 이용하여 구한다."},{"n":2,"html":"관측 대상의 상대적 거리의 정확도를 높이기 위해 적합 정도를 스트레스 값(Stress Value)로 나타낸다."},{"n":3,"html":"스트레스 값은 0에 가까울수록 적합도가 좋음을 나타낸다."},{"n":4,"html":"개체들 사이의 유사성과 비유사성을 측정하여 차원을 축소하기 위해 사용한다."}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. 다차원척도법(MDS)은 주로 관측 대상들 간의 거리나 유사성 정보를 저차원 공간으로 효과적으로 시각화하거나 축소하는 데 초점을 맞춥니다. 4번의 설명은 개체들 간의 유사성과 비유사성을 측정하는 부분은 맞지만, MDS의 주된 목적이 단순히 측정에 그치는 것이 아니라, 이러한 측정 결과를 바탕으로 고차원 데이터를 이해하기 쉬운 저차원 공간(주로 2차원이나 3차원)으로 차원을 축소하여 시각화하는 데 있습니다. 따라서 \"측정하기 위해 사용한다\"는 표현은 MDS의 핵심 기능, 즉 차원 축소와 시각화의 중요성을 간과하고 있어 가장 적절하지 않은 설명입니다. 1, 2, 3번은 각각 MDS의 거리 계산 방법, 적합도 평가 지표, 그리고 그 해석에 대해 올바르게 설명하고 있습니다.</p>"]},"rate":45,"rateN":4808},{"id":"62369","number":33,"category":"데이터 분석","type":"choice","subject":"앙상블 모형의 특징으로 올바르지 않은 것은?","choices":[{"n":1,"html":"성능을 분산시키기 때문에 과대적합(overfitting) 감소 효과가 있다."},{"n":2,"html":"각 모형의 상호연관성이 높을수록 정확도 또한 높아진다."},{"n":3,"html":"여러 개의 모형의 결과를 종합하여 정확도를 높이는 방법이다."},{"n":4,"html":"Bagging, Boosting 등 다양한 방법의 앙상블 기법이 존재한다."}],"answer":[2],"explain":{"ai":["<p>앙상블 모형은 여러 개의 모형을 결합하여 더 나은 성능을 얻는 기법입니다. 각 모형의 결과를 종합하여 정확도를 높이는 방법이기 때문에 다양한 기법을 활용할 수 있습니다. </p>\n<p>성능을 분산시키기 때문에 과대적합을 감소시키는 효과가 있습니다. 또한 여러 개의 모형의 결과를 종합하여 정확도를 높이는 방법이기 때문에 3번과 4번은 올바른 특징입니다.</p>\n<p>그러나 각 모형의 상호연관성이 높을수록 정확도가 높아지는 것은 아닙니다. 각 모형의 상호연관성이 높을수록 모형의 다양성이 감소하고, 의사결정樹나 신경망 등에서 각각의 학습 데이터가 서로 독립적이지 않기 때문에 최종 결과의 정확도가 오히려 떨어질 수 있습니다. 따라서 2번은 올바르지 않은 특징입니다.</p>"]},"rate":59,"rateN":4107},{"id":"62370","number":34,"category":"데이터 분석","type":"choice","subject":"이상치 관련한 설명으로 가장 옳지 않은 것은?","choices":[{"n":1,"html":"DBSCAN 군집을 실행해 군집에 포함되지 않은 것을 이상치로 한다."},{"n":2,"html":"ESD 방법에서는 평균 -3*표준편차보다 작거나, 평균 +3*표준편차보다 큰 데이터를 이상치로 규정한다."},{"n":3,"html":"기하평균을 이용하는 경우 기하평균 -2.5*표준편차 보다 작거나, 기하평균 +2.5*표준편차보다 큰 데이터를 이상치로 규정한다."},{"n":4,"html":"IQR을 사용하는 방식의 경우 Q2(중위수)+1.5*IQR 보다 크거나 Q2(중위수)-1.5*IQR 작은 데이터를 이상치로 규정한다."}],"answer":[4],"explain":{"ai":["<p>이상치 관련 설명 중 가장 옳지 않은 것은 IQR을 사용하는 방식의 경우 Q2(중위수)+1.5<em>IQR 보다 크거나 Q2(중위수)-1.5</em>IQR 작은 데이터를 이상치로 규정한다는 내용이다. IQR은 사분위수 범위라고 하는데 1사분위수와 3사분위수의 차이이다. 따라서 IQR은 Q1(1사분위수)와 Q3(3사분위수)로 계산이 된다. 즉 Q1 - 1.5 <em> IQR 보다 작은 값과 Q3 + 1.5 </em> IQR 보다 큰 값을 이상치로 판단한다. 중위수는 2사분위수와 같은 개념이다.</p>"]},"rate":62,"rateN":3739},{"id":"62371","number":35,"category":"데이터 분석","type":"choice","subject":"군집분석에 대한 설명으로 적절하지 않은 것은?","choices":[{"n":1,"html":"집단별 특성이 유사할 경우 안정성이 높다."},{"n":2,"html":"유사성을 이용하여 몇 개의 집단으로 그룹화하는 분석이다."},{"n":3,"html":"군집분석은 집단 간 이질성과 집단 내 동질성이 모두 낮아지는 방향으로 군집을 만든다."},{"n":4,"html":"비계층적 군집분석 기법의 경우 사용자가 사전 지식 없이 그룹의 수를 정해주는 일이 많기 때문에 결과가 잘 나오지 않을 수 있다."}],"answer":[3],"wiki":[{"title":"군집 분석","url":"https://itwiki.kr/w/군집 분석"}],"explain":{"ai":["<p>정답은 3번입니다. 군집분석의 핵심 목표는 집단 내의 동질성을 높이고 집단 간의 이질성을 높이는 것입니다. 즉, 군집분석은 같은 군집 내의 데이터들 간에 유사성을 극대화하고, 다른 군집들 간에는 차별성을 만드는 방식으로 군집을 형성합니다. 따라서 보기 3번이 말하는 \"집단 간 이질성과 집단 내 동질성이 모두 낮아지는 방향으로 군집을 만든다\"는 군집분석의 본질과 맞지 않습니다. 다른 보기들은 군집분석의 정의와 특성을 올바르게 설명하고 있습니다.</p>"]},"rate":80,"rateN":3150},{"id":"62372","number":36,"category":"데이터 분석","type":"choice","subject":"의사결정나무의 특징으로 알맞지 않은 것은?","choices":[{"n":1,"html":"상관성이 높은 변수가 있어도 영향을 받지 않는다."},{"n":2,"html":"비정상적인 잡음 데이터에 대해서는 민감하게 분류한다."},{"n":3,"html":"목적 변수가 이산형(범주형)인 경우와 연속형일 경우 모두 사용할 수 있다."},{"n":4,"html":"설명력이 좋으며, 과대적합에 취약한 특징이 있다."}],"answer":[2],"explain":{"ai":["<p>의사결정나무는 데이터 분류와 예측에 널리 쓰이는 모델이지만, 각 특징을 정확히 이해하는 것이 중요하다. </p>\n<p>1번은 맞다. 의사결정나무는 독립 변수 간의 상관성에 크게 영향을 받지 않고, 각 변수의 기여도를 개별적으로 평가한다.</p>\n<p>3번도 정확하다. 이 모델은 목적 변수가 범주형이든, 연속형이든 적용 가능하다. 단, 연속형 변수의 경우 주로 회귀 트리 형태로 사용된다.</p>\n<p>4번은 부분적으로 맞다. 의사결정나무는 해석이 용이하고 복잡한 관계를 시각적으로 표현할 수 있어 설명력이 뛰어나지만, 깊이가 깊어질수록 과대적합(overfitting)의 위험이 증가한다.</p>\n<p>그러나 정답은 2번이다. 의사결정나무는 잡음 데이터에 대해 <strong>상대적으로 덜 민감</strong>하다. 특히, 충분히 큰 학습 데이터셋을 사용하면 잡음에 의한 영향을 줄일 수 있다. 따라서 \"비정상적인 잡음 데이터에 대해서는 민감하게 분류한다\"는 설명은 의사결정나무의 특징과 맞지 않다. 이 모델은 오히려 단순화된 결정 규칙을 통해 잡음의 영향을 최소화하려는 경향이 있다.</p>"]},"rate":46,"rateN":4669},{"id":"62373","number":37,"category":"데이터 분석","type":"choice","subject":"데이터마이닝을 위한 데이터 분할과 관련된 설명 중 알맞지 않은 것은?","choices":[{"n":1,"html":"데이터는 학습용, 검증용, 평가용 데이터로 분할하여 사용할 수 있다."},{"n":2,"html":"검증용 데이터(validation data)는 학습과정에서 사용되지 않는다."},{"n":3,"html":"검증용 데이터는 훈련에 사용되지 않는다."},{"n":4,"html":"데이터 수가 적을 때는 교차 검증을 사용한다."}],"answer":[2],"explain":{"ai":["<p>데이터마이닝에서 데이터 분할은 데이터를 학습용, 검증용, 평가용으로 나누는 것을 말합니다.こう 분할함으로써 각 단계에서 사용되는 데이터가 다르기 때문에 데이터의 재사용을 줄일 수 있고, 모델의 성능을 향상시키는데 도움이 됩니다. </p>\n<p>1번의 경우 데이터를 학습용, 검증용, 평가용으로 나누어 사용할 수 있으므로 이 설명은 적절합니다. </p>\n<p>3번의 경우 검증용 데이터는 훈련에 사용되지 않기 때문에 이 설명도 적절합니다. </p>\n<p>4번의 경우 데이터 수가 적을 때 교차 검증을 사용하므로 이 설명 또한 적절합니다. </p>\n<p>2번의 경우 검증용 데이터는 실제로 학습과정에서 사용되지 않는다는 의미로 해석되는데 실제로는 학습과정에서 모델의 성능을 평가하고 개선하기 위해 사용되기 때문에 이 설명은 적절하지 않습니다. 따라서 정답은 2번입니다.</p>"]},"rate":52,"rateN":4225},{"id":"62374","number":38,"category":"데이터 분석","type":"choice","subject":"확률적 표본추출 방법이 아닌 것은?","choices":[{"n":1,"html":"단순 무작위 추출법"},{"n":2,"html":"계통 추출법"},{"n":3,"html":"집단 추출법"},{"n":4,"html":"층화 추출법"}],"answer":[3],"explain":{"ai":["<p>확률적 표본추출 방법이란 어떤 표본이 선택될 가능성이 동일하도록 표본을 추출하는 방법을 말합니다. 주어진 보기 중에서 확률적 표본추출 방법이 아닌 것은 집단 추출법입니다. 집단 추출법은 전체 집단을 여러 개의 작은 집단으로 나누고, 이 중 일부 집단을 무작위로 선택하여 해당 집단에 속한 모든 요소를 표본으로 추출하는 방법입니다. 이렇게 하면 모든 요소가 선택될 가능성이 동일하지 않기 때문에 확률적 표본추출 방법에 해당하지 않습니다. 다른 옵션인 단순 무작위 추출법, 계통 추출법, 층화 추출법은 모두 확률적 표본추출 방법입니다. 그러므로 정답은 3번입니다.</p>"]},"rate":51,"rateN":4556},{"id":"62375","number":39,"category":"데이터 분석","type":"choice","subject":"코드 실행 결과에 대한 설명으로 적절한 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"회귀모형은 유의수준 5%하에서 통계적으로 유의미하다."},{"n":2,"html":"모든 회귀계수들이 유의미하다."},{"n":3,"html":"설명력은 7.165 이다."},{"n":4,"html":"데이터의 개수는 41개 이다."}],"answer":[1],"rate":62,"rateN":3793},{"id":"62376","number":40,"category":"데이터 분석","type":"choice","subject":"데이터 전처리 과정에 대한 설명으로 올바른 것은 무엇인가?","choices":[{"n":1,"html":"결측치는 연산에 아무런 방해가 되지 않으므로 그대로 두어도 무방하다."},{"n":2,"html":"데이터 특성을 파악하고 통찰을 얻기 위한 방법을 데이터 EDA라고 한다."},{"n":3,"html":"모든 분석의 이상치는 시간이 오래 걸리더라도 모두 찾아내어 제거한다."},{"n":4,"html":"데이터 변환을 통해 정규분포 형태의 데이터로 만들면 데이터가 왜곡되어 올바른 학습이 되지 않는다."}],"answer":[2],"explain":{"ai":["<p>데이터 전처리 과정은 데이터 분석의 첫 단계로 데이터의 질을 향상시키기 위한 작업이다. 데이터 전처리 과정에서 데이터의 특성을 파악하고 통찰을 얻기 위한 방법을 데이터 탐색적 데이터 분석, 즉 EDA라고 하는데 2번이 이에 해당한다. </p>\n<p>1번은 결측치는 연산에 방해가 되므로 제거หร 수정해야 하는 것으로 그대로 두면 안된다. 3번은 이상치는 분석 결과의 신뢰도를 떨어뜨리므로 찾고 제거하는 것이 좋으나, 모든 이상치를 제거하기는 어렵다. 4번은 데이터 변환을 통해 정규분포 형태의 데이터로 만드는 것은 데이터의 특성을 더 잘 이해하고 분석하기 위함이므로 데이터가 왜곡되어 올바른 학습이 되지 않는다는 말은 옳지 않다.</p>"]},"rate":76,"rateN":3474},{"id":"62377","number":41,"category":"데이터 분석","type":"choice","subject":"변수 가공에 대한 설명으로 적절하지 않은 것은?","choices":[{"n":1,"html":"구간화의 개수가 감소하면 정확도는 높아지지만 속도가 느려진다."},{"n":2,"html":"log, sqrt를 취하면 큰 값을 작게 만들 수 있다 - 오른쪽 꼬리 긴 분포에 사용"},{"n":3,"html":"제곱, exp를 취하면 작은 값을 크게 만들 수 있다 - 왼쪽 꼬리 긴 분포에 사용"},{"n":4,"html":"MinMax Normalization을 하면 값이 0~1 사이의 범위로 변경된다."}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. 구간화의 개수가 줄어들면 일반적으로 분석의 복잡성은 감소하고 처리 속도는 빨라질 수 있지만, 정확도는 반드시 높아지는 것이 아닙니다. 오히려 구간이 너무 적으면 데이터의 세부적인 패턴을 포착하는 데 실패하여 정확도가 떨어질 수 있습니다. 정확도는 데이터의 특성과 구간화 방법에 따라 다양하게 변동하며, 단순히 구간 개수만으로 증가하거나 감소한다고 단정 지을 수 없습니다.</p>\n<p>다른 보기들은 다음과 같이 설명할 수 있습니다:</p>\n<ul>\n<li>2번: 로그(log)와 제곱근(sqrt) 변환은 큰 값들을 축소시켜 데이터의 분산을 줄이고, 특히 오른쪽 꼬리가 긴 분포를 정규화하는 데 효과적입니다.</li>\n<li>3번: 제곱(^2) 또는 지수(exp) 변환은 작은 값들을 확대시켜 왼쪽 꼬리가 긴 분포를 다룰 때 유용합니다.</li>\n<li>4번: MinMax Normalization은 가장 작은 값을 0, 가장 큰 값을 1로 조정하여 모든 값이 0과 1 사이에 위치하도록 만드는 기법으로 정확하게 설명하고 있습니다.</li>\n</ul>"]},"rate":69,"rateN":3285},{"id":"62378","number":42,"category":"데이터 분석","type":"choice","subject":"다음이 설명하는 시계열 모형은 무엇인가?","extra":"<pre class=\"contents\">\"자기 자신의 과거자료로 설명하는 모형으로 백색잡음의 현재값과 자기자신의 과거값의 가중합으로 선형성을 표현하는 정상시계열 모형이다.\"</pre>","choices":[{"n":1,"html":"MA 모형"},{"n":2,"html":"AR 모형"},{"n":3,"html":"의사결정나무"},{"n":4,"html":"인공신경망"}],"answer":[2],"explain":{"ai":["<p>정답은 2번, AR 모형입니다. 지문에서 설명하는 모형은 현재 값이 과거 자기 자신의 값들에 의해 결정된다는 점에 초점을 맞추고 있습니다. \"자기 자신의 과거자료로 설명\"과 \"과거의 값의 가중합으로 선형성을 표현\"이라는 부분은 Autoregressive (AR) 모형의 정의와 일치합니다. AR 모형은 과거 특정 시점의 관측치들의 선형 조합으로 현재 값을 예측하는 모형으로, 이러한 특성이 지문과 정확히 부합합니다. 다른 옵션들인 MA 모형, 의사결정나무, 인공신경망은 각각 다른 원리와 적용 범위를 가지고 있어 지문의 설명과 맞지 않습니다.</p>"]},"rate":65,"rateN":3737},{"id":"62379","number":43,"category":"데이터 분석","type":"choice","subject":"다음이 설명하는 앙상블 모형의 종류는 무엇인가?","extra":"<pre class=\"contents\">\"배깅(bagging)에 랜덤 과정을 추가한 방법으로 노드 내 데이터를 자식 노드로 나누는 기준을 정할 때 모든 예측 변수에서 최적의 분할을 선택하는 대신, 설명변수의 일부분만을 고려함으로 성능을 높이는 방법을 사용한다.\"</pre>","choices":[{"n":1,"html":"랜덤 포레스트"},{"n":2,"html":"로지스틱 회귀 분석"},{"n":3,"html":"K-NN"},{"n":4,"html":"붓스트랩"}],"answer":[1],"explain":{"ai":["<p>배깅은 모델의 성능을 향상시키기 위해 여러 개의 모델을 결합하는 앙상블 기법 중 하나입니다. 랜덤 포레스트는 이런 배깅에 랜덤 요소를 더한 방법입니다. 랜덤 포레스트에서 노드를 분할할 때, 모든 예측 변수 중 일부만을 고려하여 분할 기준을 정합니다. 이렇게 하면 모델의 과적합을 방지하고, 여러 개의 트리 모델을 결합하여 전반적인 성능을 향상시킵니다.such 방법은 랜덤 포레스트의 특징입니다. 따라서 해당 방법은 랜덤 포레스트입니다.</p>"]},"rate":66,"rateN":3681},{"id":"62380","number":44,"category":"데이터 분석","type":"short","subject":"다음 오분류표를 사용하여 F1-score를 구하시오.","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","shortAnswer":"6/19"},{"id":"62381","number":45,"category":"데이터 분석","type":"short","subject":"이산확률변수 X가 가능한 값으로 1,2,4 가 있다. \r\nP(X=1) = 0.3 이고 기댓값이 2.7 일 때 P(X=2)는 무엇인가?","shortAnswer":"0.2","explain":{"ai":["<p>이산확률변수 X의 기댓값은 E(X) = ΣxP(X=x)로 계산됩니다. \n기댓값은 2.7이고 P(X=1) = 0.3이며 X의 가능한 값은 1, 2, 4입니다. \nE(X) = 1<em>P(X=1) + 2</em>P(X=2) + 4<em>P(X=4) = 2.7 \nP(X=1) = 0.3 \n1</em>0.3 + 2<em>P(X=2) + 4</em>P(X=4) = 2.7 \n0.3 + 2<em>P(X=2) + 4</em>P(X=4) = 2.7 \n2<em>P(X=2) + 4</em>P(X=4) = 2.7 - 0.3 \n2<em>P(X=2) + 4</em>P(X=4) = 2.4 \n또한 모든 확률의 합은 1이므로 \nP(X=1) + P(X=2) + P(X=4) = 1 \n0.3 + P(X=2) + P(X=4) = 1 \nP(X=2) + P(X=4) = 0.7 \n위의 두 방정식으로 P(X=2)를 계산합니다. \n2<em>P(X=2) + 4</em>(0.7 - P(X=2)) = 2.4 \n2<em>P(X=2) + 2.8 - 4</em>P(X=2) = 2.4 \n-2<em>P(X=2) = 2.4 - 2.8 \n-2</em>P(X=2) = -0.4 \nP(X=2) = 0.2 \n따라서 P(X=2)는 0.2입니다.</p>"]}},{"id":"62382","number":46,"category":"데이터 분석","type":"short","subject":"우등반에 들어가기 위해서는 어느 시험에서 상위 2% 안에 들어야 한다.\r\n해당 시험 점수의 평균이 85점이고 표준편차가 5일 때, 우등반에 들어가기 위한 최소 시험 점수는?\r\n(단, P(Z","shortAnswer":"95.25","explain":{"ai":["<p>우등반에 들어가기 위해서는 상위 2% 안에 들어야 하므로, 표준 정규 분포에서 Z-값을 찾는 것이 목표입니다. 우등반의 기준은 전체 분포 중 상위 2%를 의미하므로, Z-값은 약 2.05가 됩니다. </p>\n<p>이제 Z-값을 사용하여 원래 점수에 대한 최소 점수를 계산할 수 있습니다. </p>\n<p>Z = (X - μ) / σ </p>\n<p>여기서 X는 원하는 점수, μ는 평균(85), σ는 표준편차(5)입니다. </p>\n<p>Z = 2.05 \n→ 2.05 = (X - 85) / 5 \n→ X - 85 = 2.05 * 5 \n→ X - 85 = 10.25 \n→ X = 10.25 + 85 \n→ X = 95.25 </p>\n<p>따라서 우등반에 들어가기 위한 최소 시험 점수는 95.25점 이상입니다.</p>"]}}]};